//! Naming and validation shared by both macros, so the struct generated by
//! [`macro@crate::ffi_controller`] always matches the fields and types the
//! [`macro@crate::ffi_callbacks`] implementations expect.

use quote::format_ident;
use syn::{Attribute, Error, Generics, Ident, Type, spanned::Spanned};

/// Prefix of every generated C type
const PREFIX: &str = "gbeed";

/// Types that can cross the C boundary as they are
const PRIMITIVES: &[&str] = &[
    "u8", "u16", "u32", "u64", "usize", "i8", "i16", "i32", "i64", "isize", "f32", "f64", "bool",
];

/// C struct generated for a trait: `Renderer` -> `<PREFIX>Renderer`
pub fn struct_ident(trait_ident: &Ident) -> Ident { format_ident!("{PREFIX}{trait_ident}") }

/// Field holding the callbacks of a trait in the controller struct: `AudioPlayer` -> `audio_player`
pub fn field_ident(trait_ident: &Ident) -> Ident {
    let snake = trait_ident
        .to_string()
        .chars()
        .enumerate()
        .flat_map(|(i, c)| {
            let separator = if i > 0 && c.is_uppercase() {
                Some('_')
            } else {
                None
            };
            std::iter::chain(separator, c.to_lowercase())
        })
        .collect::<String>();

    format_ident!("{snake}")
}

pub fn reject_generics(generics: &Generics, message: &str) -> syn::Result<()> {
    match generics.params.is_empty() {
        true => Ok(()),
        false => Err(Error::new(generics.span(), message)),
    }
}

pub fn is_primitive(ty: &Type) -> bool {
    match ty {
        Type::Path(path) if path.qself.is_none() => path
            .path
            .get_ident()
            .is_some_and(|ident| PRIMITIVES.iter().any(|p| ident == p)),
        _ => false,
    }
}

pub fn docs(attrs: &[Attribute]) -> impl Iterator<Item = &Attribute> {
    attrs.iter().filter(|attr| attr.path().is_ident("doc"))
}
